// A representative V27 campaign and city, generated by the exact published V27 commit.
// Compare both initial load and continued progression, not just JSON parseability.
const assert=require('node:assert/strict');
global.window={};require('../data.js');require('../sim.js');require('../city.js');
const fixture=JSON.parse(require('node:zlib').gunzipSync(require('node:fs').readFileSync(require('node:path').join(__dirname,'fixtures/v27-save-compatibility.json.gz'))));
const S=window.VisionSim,C=window.VisionCity;
S.setWorld({setProjectState(){},place:(lo,la)=>[lo,la]});
for(const [name,api,tick] of [['national',S,()=>S.tickMonth()],['city',C,()=>C.tick()]]){
  api.load(fixture[name].input);
  assert.deepEqual(JSON.parse(api.serialize()),JSON.parse(fixture[name].loaded),name+' V27 state must load unchanged');
  for(let i=0;i<3;i++)tick();
  assert.deepEqual(JSON.parse(api.serialize()),JSON.parse(fixture[name].after3),name+' progression must match V27');
  console.log('PASS V27 '+name+' save loads unchanged and matches three more months of V27 progression');
}
